mapper.select:
select
a.device_id,
a.device_name,
a.device_type,
a.device_code,
a.station_id,
a.relation_code,
a.create_time,
a.update_time,
a.remark
from t_cfg_device a
where 1 = 1
 and a.device_id = #{deviceId, jdbcType=VARCHAR}
 and a.device_name = #{deviceName, jdbcType=VARCHAR}
 and a.device_type = #{deviceType, jdbcType=VARCHAR}
 and a.device_code = #{deviceCode, jdbcType=VARCHAR}
 and a.station_id = #{stationId, jdbcType=BIGINT}
 and a.relation_code = #{relationCode, jdbcType=VARCHAR}
 and a.create_time = #{createTime, jdbcType=TIMESTAMP}
 and a.update_time = #{updateTime, jdbcType=TIMESTAMP}
 and a.remark = #{remark, jdbcType=VARCHAR}

       SELECT a.device_id as deviceId,a.device_name as deviceName,b.mete_name as meteName,b.mete_kind as meteKind,b.mete_code as meteCode,b.mete_explain_type as meteExplainType,d.isshield as isShield,h.dict_note as meteKindName
	   FROM t_dict_business h,t_cfg_device a,t_cfg_mete b,t_cfg_telemeter d
	   WHERE
        a.device_id = d.device_id and  b.mete_id = d.mete_id and h.dict_code = b.mete_kind
         and a.device_type = #{deviceType, jdbcType=VARCHAR}
         and h.dict_code = #{meteKind, jdbcType=VARCHAR}
         and b.mete_name like concat('%',#{meteName, jdbcType=VARCHAR},'%')
        UNION all(
        SELECT a.device_id as deviceId,a.device_name as deviceName,b.mete_name as meteName,b.mete_kind as meteKind,b.mete_code as meteCode,b.mete_explain_type as meteExplainType,e.isshield as isShield,h.dict_note as meteKindName
        FROM t_dict_business h,t_cfg_device a,t_cfg_mete b,t_cfg_telesignal e
        WHERE
        a.device_id = e.device_id and  b.mete_id = e.mete_id and h.dict_code = b.mete_kind
         and a.device_type = #{deviceType, jdbcType=VARCHAR}
         and h.dict_code = #{meteKind, jdbcType=VARCHAR}
         and b.mete_name like concat('%',#{meteName, jdbcType=VARCHAR},'%')
        )
        UNION all(
        SELECT a.device_id as deviceId,a.device_name as deviceName,b.mete_name as meteName,b.mete_kind as meteKind,b.mete_code as meteCode,b.mete_explain_type as meteExplainType,'null' as isShield,h.dict_note as meteKindName
        FROM t_dict_business h,t_cfg_device a,t_cfg_mete b,t_cfg_teleadjust f
        WHERE
        a.device_id = f.device_id and  b.mete_id = f.mete_id and h.dict_code = b.mete_kind
         and a.device_type = #{deviceType, jdbcType=VARCHAR}
         and h.dict_code= #{meteKind, jdbcType=VARCHAR}
         and b.mete_name like concat('%',#{meteName, jdbcType=VARCHAR},'%')
        )UNION all(
        SELECT a.device_id as deviceId,a.device_name as deviceName,b.mete_name as meteName,b.mete_kind as meteKind,b.mete_code as meteCode,b.mete_explain_type as meteExplainType,'null' as isShield,h.dict_note as meteKindName
        FROM t_dict_business h,t_cfg_device a,t_cfg_mete b,t_cfg_telecontrol g
        WHERE
        a.device_id = g.device_id and  b.mete_id = g.mete_id and h.dict_code = b.mete_kind
         and a.device_type = #{deviceType, jdbcType=VARCHAR}
         and h.dict_code = #{meteKind, jdbcType=VARCHAR}
         and b.mete_name like concat('%',#{meteName, jdbcType=VARCHAR},'%')
        )
